const SubscriptionGuard={PLAN_CONFIGS:{Starter:{features:["basic_workflow","standard_reports"],ai_assistant:!1,white_label:!1,analytics:!1,repository:!1},Professional:{features:["full_workflow","advanced_analytics","repository","ai_assistant","audit_logs"],ai_assistant:!0,white_label:!1,analytics:!0,repository:!0},Enterprise:{features:["full_workflow","advanced_analytics","repository","ai_assistant","audit_logs","white_label","multi_plant","api_access"],ai_assistant:!0,white_label:!0,analytics:!0,repository:!0}},getCurrentPlan(){try{const user=JSON.parse(sessionStorage.getItem("user"));return user?.subscription_plan||"Starter"}catch(e){return"Starter"}},hasFeature(featureName){const plan=this.getCurrentPlan(),config=this.PLAN_CONFIGS[plan]||this.PLAN_CONFIGS.Starter;return!0===config[featureName]||config.features&&config.features.includes(featureName)},init(){document.addEventListener("click",e=>{const lockEl=e.target.closest("[data-feature-lock]");if(lockEl){const feature=lockEl.getAttribute("data-feature-lock");this.hasFeature(feature)||(e.preventDefault(),e.stopPropagation(),this.showUpgradeModal(feature))}},!0),this.applyUIGuards()},applyUIGuards(){document.querySelectorAll("[data-feature-lock]").forEach(el=>{const feature=el.getAttribute("data-feature-lock");if(!this.hasFeature(feature)){if(!el.querySelector(".fa-lock")){const lock=document.createElement("i");lock.className="fas fa-lock ms-2 text-warning",lock.style.fontSize="0.8em",el.appendChild(lock)}el.classList.add("feature-locked"),el.title=`Upgrade your plan to access ${feature.replace("_"," ")}`}})},showUpgradeModal(feature){if(window.UpgradeModal)window.UpgradeModal.show(feature);else{const msg=`The feature '${feature.replace("_"," ")}' is only available on Professional or Enterprise plans. Would you like to view our pricing plans?`;confirm(msg)&&(window.location.href="index.html#pricing")}}};"loading"===document.readyState?document.addEventListener("DOMContentLoaded",()=>SubscriptionGuard.init()):SubscriptionGuard.init(),window.SubscriptionGuard=SubscriptionGuard;